package api

import "testing"

func TestDeactivatedAgentExcludedFromListUnlessIncluded(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{"name": "Ada", "email": "a@example.com"})
	id := jsonNum(agent.body["id"])
	doRequest(t, srv.URL, "POST", "/api/agents/"+id+"/deactivate", nil)

	list := doRequest(t, srv.URL, "GET", "/api/agents", nil)
	if len(list.list) != 0 {
		t.Fatalf("expected 0 active agents, got %d", len(list.list))
	}

	withInactive := doRequest(t, srv.URL, "GET", "/api/agents?includeInactive=true", nil)
	if len(withInactive.list) != 1 {
		t.Fatalf("expected 1 agent with includeInactive=true, got %d", len(withInactive.list))
	}
}

func TestDeactivatedAgentRejectsCreationAndReassignment(t *testing.T) {
	srv := startServer(t)
	defer srv.Close()

	agent := doRequest(t, srv.URL, "POST", "/api/agents", map[string]any{"name": "Ada", "email": "a@example.com"})
	agentID := agent.body["id"]
	agentIDStr := jsonNum(agentID)

	unassigned := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "A"})
	unassignedID := jsonNum(unassigned.body["id"])

	doRequest(t, srv.URL, "POST", "/api/agents/"+agentIDStr+"/deactivate", nil)

	rejectedCreate := doRequest(t, srv.URL, "POST", "/api/tickets", map[string]any{"subject": "B", "agentId": agentID})
	if rejectedCreate.status != 400 {
		t.Fatalf("expected 400 on creation with deactivated agent, got %d", rejectedCreate.status)
	}

	rejectedReassign := doRequest(t, srv.URL, "PATCH", "/api/tickets/"+unassignedID, map[string]any{"agentId": agentID})
	if rejectedReassign.status != 400 {
		t.Fatalf("expected 400 on reassignment to a deactivated agent, got %d", rejectedReassign.status)
	}
}

